                    value = value * modCombination(i + k, k) % MOD;
                    dp[i + k][nextJ] = (dp[i + k][nextJ] + value) % MOD;
                }
            }
        }

        long answer = 0;
        for (int j = 1; j <= x; j++) {
            answer = (answer + dp[n][j]) % MOD;
        }

        out.println((answer % MOD + MOD) % MOD);
        out.flush();
    }

